import React, { useEffect, useMemo, useState } from 'react';
import { 
  Typography, 
  Box, 
  Table, 
  TableBody, 
  TableCell, 
  TableContainer, 
  TableHead, 
  TableRow, 
  Paper,
  Chip,
  TextField,
  Button,
  Alert,
  Snackbar,
  Stack,
  Select,
  MenuItem,
  IconButton,
  Tooltip,
  CircularProgress,
} from '@mui/material';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import DeleteIcon from '@mui/icons-material/Delete';
import { useAppSelector } from '../../store/hooks';
import { Task } from '../../types/domain';
import { 
  useCreateTask, 
  useUpdateTask, 
  useDeleteTask,
  useProjectDetails 
} from '../../services/queries';

const hasCycle = (tasks: Task[]): boolean => {
  const adj = new Map<number, number[]>();
  // Use global ID for internal cycle detection to avoid issues if project_task_id is not unique globally
  tasks.forEach((t) => adj.set(t.id, t.dependencies)); 
  const visiting = new Set<number>();
  const visited = new Set<number>();

  const dfs = (id: number): boolean => {
    if (visiting.has(id)) return true;
    if (visited.has(id)) return false;
    visiting.add(id);
    for (const nei of adj.get(id) || []) {
      if (!adj.has(nei)) continue; // Ensure predecessor exists in current task list
      if (dfs(nei)) return true;
    }
    visiting.delete(id);
    visited.add(id);
    return false;
  };

  for (const id of adj.keys()) {
    if (dfs(id)) return true;
  }
  return false;
};

const WbsTable: React.FC = () => {
  const { currentProject } = useAppSelector((state) => state.projects);
  const [selectedTaskId, setSelectedTaskId] = useState<number | null>(null);
  const [drafts, setDrafts] = useState<Record<number, Partial<Task>>>({});
  // New local state for predecessor input, managing the raw string value
  const [predecessorInputDraft, setPredecessorInputDraft] = useState<Record<number, string>>({}); 
  const [snack, setSnack] = useState<{ open: boolean; msg: string; severity: 'success' | 'error' | 'info' }>({
    open: false,
    msg: '',
    severity: 'success',
  });

  // Fetch project details including tasks and resources
  const { data: projectDetails, isLoading } = useProjectDetails(currentProject?.id || null);
  const rawTasks = useMemo(() => projectDetails?.tasks || [], [projectDetails?.tasks]);
  const tasks = useMemo(
    () => rawTasks.map((t) => ({ ...t, dependencies: t.dependencies || [] })), // Use dependencies
    [rawTasks]
  );
  const resources = useMemo(() => projectDetails?.resources || [], [projectDetails?.resources]);

  // Mutations for task management
  const createTaskMutation = useCreateTask(currentProject?.id || 0);
  const updateTaskMutation = useUpdateTask(currentProject?.id || 0);
  const deleteTaskMutation = useDeleteTask(currentProject?.id || 0);

  // Map for quick lookup of tasks by their GLOBAL ID
  const taskMap = useMemo(() => new Map(tasks.map((t) => [t.id, t])), [tasks]); 
  // Map for quick lookup of tasks by their PROJECT_TASK_ID
  const projectTaskMap = useMemo(() => new Map(tasks.map((t) => [`${t.project_id}-${t.project_task_id}`, t])), [tasks]);


  // Check for missing predecessors. This logic still refers to global IDs in task.dependencies.
  const missingPreds = useMemo(() => {
    const missing = new Set<number>();
    tasks.forEach((t) => (t.dependencies || []).forEach((pid) => { 
      // Check if the global ID exists. If dependencies were changed to project_task_id, this would need a lookup.
      if (!taskMap.has(pid)) missing.add(t.id); 
    }));
    return missing;
  }, [tasks, taskMap]);

  // Effect to initialize predecessorInputDraft when tasks load or change
  useEffect(() => {
    const newDraft: Record<number, string> = {};
    tasks.forEach(task => {
      // Initialize with the current task's dependencies (global IDs), joined by ', '
      // If we want to display project_task_id here, we'd need to map task.dependencies (global IDs)
      // back to their respective project_task_ids for display.
      newDraft[task.id] = (task.dependencies || [])
        .map(depId => taskMap.get(depId)?.project_task_id || depId) // Display project_task_id if found, else global ID
        .join(', ');
    });
    setPredecessorInputDraft(newDraft);
  }, [tasks, taskMap]);

  if (!currentProject) {
    return (
      <Box sx={{ textAlign: 'center', mt: 4 }}>
        <Typography variant="h6" color="text.secondary">
          Select a project to view its Work Breakdown Structure.
        </Typography>
      </Box>
    );
  }

  if (isLoading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100%' }}>
        <CircularProgress />
      </Box>
    );
  }

  // Helper to convert project_task_id back to global ID for mutations
  const getGlobalTaskId = (projectTaskId: number): number | undefined => {
    // This is simplified: assumes unique project_task_id within the *current* project view
    // A more robust solution might need a map from (project_id, project_task_id) to global ID
    const task = tasks.find(t => t.project_task_id === projectTaskId);
    return task?.id;
  };

  const handleFieldChange = async (taskId: number, field: keyof Task, value: string | number | number[]) => {
    await updateTaskMutation.mutateAsync({
      taskId,
      data: { [field]: value },
    });
  };

  const parsePredecessorInput = (input: string): number[] => {
    return input
      .split(',')
      .map((v) => v.trim())
      .filter(Boolean)
      .map(Number)
      .filter(id => !isNaN(id))
      .map(projectTaskId => {
        // Convert input project_task_id to global ID for the backend
        const globalId = getGlobalTaskId(projectTaskId);
        if (globalId === undefined) {
          console.warn(`Predecessor project_task_id ${projectTaskId} not found in current project.`);
          // Optionally, return the original projectTaskId here and let backend validation handle it,
          // or filter it out. For now, we'll pass the global ID if found, else the original number.
          return projectTaskId; // This will likely result in a missing predecessor error later.
        }
        return globalId;
      });
  };

  // This function is called on onBlur of the TextField
  const handlePredecessorsBlur = async (taskId: number, value: string) => {
    const parsedGlobalIds = parsePredecessorInput(value);
    try {
      await updateTaskMutation.mutateAsync({
        taskId,
        data: { dependencies: parsedGlobalIds }, // Now sends 'dependencies' (global IDs)
      });
      setSnack({ open: true, msg: 'Predecessors saved', severity: 'success' });
    } catch (err) {
      setSnack({ open: true, msg: `Failed to save predecessors: ${err instanceof Error ? err.message : String(err)}`, severity: 'error' });
    }
  };

  const handleAddTask = async () => {
    const newTaskData = {
      text: 'New Task',
      start_date: new Date().toISOString().slice(0, 10),
      duration: 1,
      progress: 0,
      parent: null,
      cost: 0,
      dependencies: [] as number[], // Use dependencies (global IDs)
    };
    await createTaskMutation.mutateAsync(newTaskData);
  };

  const handleDeleteTask = async (taskId: number) => {
    await deleteTaskMutation.mutateAsync(taskId);
  };

  const invalidCycle = hasCycle(tasks);
  const invalidDuration = tasks.some((t) => t.duration < 0);
  const invalidNames = tasks.some((t) => !t.text || !t.text.trim());
  const invalidPredRefs = tasks.some((t) => (t.dependencies || []).some((pid) => !taskMap.has(pid))); // Use dependencies (global IDs)

  const validationError =
    invalidCycle
      ? 'Dependency cycle detected. Please fix predecessors.'
      : invalidDuration
        ? 'One or more tasks have invalid (negative) duration.'
        : invalidNames
          ? 'One or more tasks are missing a name.'
          : invalidPredRefs
            ? 'One or more predecessors refer to missing tasks.'
            : null;

  const handleIndent = async (taskId: number) => {
    const idx = tasks.findIndex((t) => t.id === taskId);
    if (idx > 0 && tasks[idx-1]) {
      const newParent = tasks[idx - 1].id; // Parent is also global ID
      await updateTaskMutation.mutateAsync({
        taskId,
        data: { parent: newParent },
      });
    }
  };

  const handleOutdent = async (taskId: number) => {
    await updateTaskMutation.mutateAsync({
      taskId,
      data: { parent: null },
    });
  };

  const getDraftValue = (task: Task, field: keyof Task) => {
    const draft = drafts[task.id];
    if (draft && draft[field] !== undefined) return draft[field] as any;
    return task[field] as any;
  };

  const setDraftValue = (taskId: number, field: keyof Task, value: any) => {
    setDrafts((prev) => ({
      ...prev,
      [taskId]: { ...(prev[taskId] || {}), [field]: value },
    }));
  };

  const commitDraftValue = async (taskId: number, field: keyof Task) => {
    const draft = drafts[taskId];
    if (!draft || draft[field] === undefined) return;
    const value = draft[field] as any;
    try {
      await handleFieldChange(taskId, field, value);
      setSnack({ open: true, msg: 'Saved', severity: 'success' });
      setDrafts((prev) => {
        const next = { ...(prev[taskId] || {}) };
        delete next[field];
        const rest = { ...prev, [taskId]: next };
        if (!Object.keys(next).length) delete rest[taskId];
        return rest;
      });
    } catch (err) {
      setSnack({ open: true, msg: 'Save failed', severity: 'error' });
    }
  };

  const isLoading_ = createTaskMutation.isPending || updateTaskMutation.isPending || deleteTaskMutation.isPending;

  return (
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', minWidth: 0 }}>
      <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 1 }}>
        <Typography variant="h6">
          Work Breakdown Structure for "{currentProject.name}"
        </Typography>
        <Button 
          variant="contained" 
          size="small" 
          onClick={handleAddTask}
          disabled={isLoading_}
        >
          Add Task
        </Button>
      </Stack>
      {validationError && <Alert severity="warning" sx={{ mb: 1 }}>{validationError}</Alert>}
      <Paper elevation={3} sx={{ borderRadius: 3, overflow: 'hidden', flex: 1, minHeight: 0 }}>
        <Box sx={{ maxHeight: '60vh', overflow: 'auto', minWidth: 0 }}>
          <TableContainer>
            <Table 
              size="small" 
