    db.refresh(db_event_log)
    return db_event_log

def delete_event_log(db: Session, event_log_id: int):
    db_event_log = db.query(models.EventLog).filter(models.EventLog.id == event_log_id).first()
    if db_event_log:
        db.delete(db_event_log)
        db.commit()
    return db_event_log

