                        helperText={Number(getDraftValue(task, 'duration')) < 0 ? 'Must be >= 0' : ''}
                        InputProps={{ sx: { fontSize: 14, py: 1 } }}
                        onChange={(e) => setDraftValue(task.id, 'duration', Number(e.target.value))}
