                      <Stack direction="row" spacing={0.5} alignItems="center" sx={{ mb: 0.5 }}>
                        <Tooltip title="Indent under previous task">
                          <span>
                            <IconButton
                              size="small"
                              onClick={() => handleIndent(task.id)}
