import React, { useEffect, useRef } from 'react';
import { gantt } from 'dhtmlx-gantt';
import 'dhtmlx-gantt/codebase/dhtmlxgantt.css';

const GanttChart: React.FC = () => {
  const ganttContainer = useRef<HTMLDivElement>(null);

