        "event_type": event.event_type,
        "timestamp": db_event.timestamp.isoformat(),
        "task_id": event.task_id,
        "risk_id": event.risk_id,
        "details": event.details or {}
    })
    
    return {"status": "event_broadcasted", "event_id": db_event.id}


